"use client";

import { useEffect, useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/auth/auth-context";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Loader2, ArrowLeft, BookHeart, Lock, Sparkles, Trash2, Eye } from "lucide-react";
import {
  createJournalEntry,
  getJournalEntries,
  analyzeJournalEntry,
  deleteJournalEntry,
} from "@/lib/api/stress-wellness";
import type { WellnessJournalEntry, SentimentAnalysis } from "@/lib/types";
import { toast } from "sonner";

export default function JournalPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const [entries, setEntries] = useState<WellnessJournalEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [saving, setSaving] = useState(false);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [viewingEntry, setViewingEntry] = useState<WellnessJournalEntry | null>(null);
  const [analysis, setAnalysis] = useState<SentimentAnalysis | null>(null);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await getJournalEntries();
      if (res.success) setEntries(res.data || []);
    } catch {
      // silent
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (user) fetchData();
  }, [user, fetchData]);

  const handleSave = async () => {
    if (!content.trim()) return;
    try {
      setSaving(true);
      const res = await createJournalEntry({
        title: title || undefined,
        content,
        isAnonymous,
      });
      if (res.success) {
        toast.success(isAnonymous ? "Anonymous entry saved" : "Journal entry saved");
        setTitle("");
        setContent("");
        setIsAnonymous(false);
        fetchData();
      }
    } catch {
      toast.error("Failed to save entry");
    } finally {
      setSaving(false);
    }
  };

  const handleAnalyze = async (entryId: string) => {
    try {
      setAnalyzingId(entryId);
      const res = await analyzeJournalEntry(entryId);
      if (res.success && res.data) {
        setAnalysis(res.data);
        toast.success("Emotional analysis complete");
        fetchData();
      }
    } catch {
      toast.error("Analysis failed");
    } finally {
      setAnalyzingId(null);
    }
  };

  const handleDelete = async (entryId: string) => {
    try {
      await deleteJournalEntry(entryId);
      toast.success("Entry deleted");
      setViewingEntry(null);
      fetchData();
    } catch {
      toast.error("Failed to delete entry");
    }
  };

  if (authLoading) return <div className="min-h-screen bg-slate-50 flex items-center justify-center"><Loader2 className="w-8 h-8 animate-spin" /></div>;
  if (!user) return null;

  return (
    <main className="min-h-screen bg-slate-50 py-8 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        <button onClick={() => router.push("/stress-wellness")} className="flex items-center gap-2 text-slate-600 hover:text-slate-900">
          <ArrowLeft className="w-4 h-4" /> Back to Wellness
        </button>

        <div className="flex items-center gap-3 mb-2">
          <div className="w-10 h-10 bg-teal-100 rounded-lg flex items-center justify-center">
            <BookHeart className="w-5 h-5 text-teal-500" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">Anonymous Journal</h1>
            <p className="text-sm text-slate-500">Express yourself freely in a private, secure space</p>
          </div>
        </div>

        {viewingEntry ? (
          <Card className="bg-white border-0 shadow-sm">
            <CardHeader className="flex flex-row items-start justify-between">
              <div>
                <CardTitle className="text-lg">{viewingEntry.title || "Untitled Entry"}</CardTitle>
                <CardDescription>{new Date(viewingEntry.createdAt).toLocaleString()}</CardDescription>
              </div>
              <div className="flex gap-2">
                {!viewingEntry.analyzedAt && (
                  <Button size="sm" variant="outline" onClick={() => handleAnalyze(viewingEntry.id)} disabled={analyzingId === viewingEntry.id}>
                    {analyzingId === viewingEntry.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    Analyze
                  </Button>
                )}
                <Button size="sm" variant="destructive" onClick={() => handleDelete(viewingEntry.id)}>
                  <Trash2 className="w-4 h-4" />
                </Button>
                <Button size="sm" variant="outline" onClick={() => { setViewingEntry(null); setAnalysis(null); }}>
                  Back
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="p-4 bg-slate-50 rounded-xl whitespace-pre-wrap text-sm text-slate-700">
                {viewingEntry.content}
              </div>
              {viewingEntry.isAnonymous && (
                <Badge variant="secondary"><Lock className="w-3 h-3 mr-1" /> Anonymous</Badge>
              )}
              {viewingEntry.sentiment && (
                <div className="p-4 bg-gradient-to-br from-indigo-50 to-purple-50 rounded-xl border border-indigo-100">
                  <h4 className="font-medium text-indigo-800 mb-2 flex items-center gap-2">
                    <Sparkles className="w-4 h-4" /> AI Emotional Analysis
                  </h4>
                  <div className="space-y-2 text-sm">
                    <p><strong>Sentiment:</strong> {(viewingEntry.sentiment as SentimentAnalysis).overallSentiment}</p>
                    {(viewingEntry.sentiment as SentimentAnalysis).stressIndicators?.length > 0 && (
                      <div>
                        <strong>Stress Indicators:</strong>
                        <ul className="list-disc list-inside text-slate-600">
                          {(viewingEntry.sentiment as SentimentAnalysis).stressIndicators.map((s, i) => <li key={i}>{s}</li>)}
                        </ul>
                      </div>
                    )}
                    {(viewingEntry.sentiment as SentimentAnalysis).recommendations?.length > 0 && (
                      <div>
                        <strong>Recommendations:</strong>
                        <ul className="list-disc list-inside text-slate-600">
                          {(viewingEntry.sentiment as SentimentAnalysis).recommendations.map((r, i) => <li key={i}>{r}</li>)}
                        </ul>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        ) : (
          <>
            {/* New Entry */}
            <Card className="bg-white border-0 shadow-sm">
              <CardHeader>
                <CardTitle className="text-lg">New Entry</CardTitle>
                <CardDescription>Write your thoughts and feelings</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <Input placeholder="Title (optional)" value={title} onChange={(e) => setTitle(e.target.value)} />
                <Textarea
                  placeholder="Write whatever is on your mind..."
                  value={content}
                  onChange={(e) => setContent(e.target.value)}
                  className="min-h-[200px]"
                />
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-2 text-sm text-slate-600 cursor-pointer">
                    <Switch checked={isAnonymous} onCheckedChange={setIsAnonymous} />
                    <Lock className="w-4 h-4" /> Save anonymously
                  </label>
                  <Button onClick={handleSave} disabled={!content.trim() || saving}>
                    {saving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                    Save Entry
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Entry List */}
            <Card className="bg-white border-0 shadow-sm">
              <CardHeader>
                <CardTitle className="text-lg">Your Journal</CardTitle>
                <CardDescription>{entries.length} entries</CardDescription>
              </CardHeader>
              <CardContent>
                {loading ? (
                  <Loader2 className="w-6 h-6 animate-spin mx-auto" />
                ) : entries.length === 0 ? (
                  <p className="text-center text-slate-500 py-8">No journal entries yet. Start writing!</p>
                ) : (
                  <div className="space-y-3">
                    {entries.map((entry) => (
                      <div
                        key={entry.id}
                        className="p-4 bg-slate-50 rounded-xl cursor-pointer hover:bg-slate-100 transition-colors"
                        onClick={() => setViewingEntry(entry)}
                      >
                        <div className="flex items-start justify-between mb-1">
                          <h4 className="font-medium text-slate-800">{entry.title || "Untitled"}</h4>
                          <div className="flex items-center gap-2">
                            {entry.analyzedAt && <Sparkles className="w-3.5 h-3.5 text-indigo-400" />}
                            {entry.isAnonymous && <Lock className="w-3.5 h-3.5 text-teal-400" />}
                          </div>
                        </div>
                        <p className="text-sm text-slate-500 line-clamp-2">{entry.content}</p>
                        <p className="text-xs text-slate-400 mt-2">{new Date(entry.createdAt).toLocaleDateString()}</p>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}
      </div>
    </main>
  );
}
